components.css:
.ds-primary { --ink: #153d28; --muted: #405c35; --green: #173f29; --green-hover: #0e3020; --surface: #fff; --line: #d7e3ce; --soft: #e2efc3; --focus: #245c35; --energy: #d4f458; --canvas: #edf5d5; }.ds-primary { font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", sans-serif; cursor: pointer;width: 100%; min-height: 58px; border: 0; border-radius: 16px; background: var(--green); color: #fff;
  padding: 16px 22px; display: flex; justify-content: center; align-items: center; gap: 12px;
  font-size: 1rem; line-height: 1.5; font-weight: 600; transition: background-color 160ms ease-out, transform 160ms ease-out; }.ds-primary svg { width: 20px; height: 20px; color: var(--energy); }.ds-primary:active { transform: scale(.985); background: var(--green-hover); }.ds-primary:focus-visible { outline: 3px solid var(--focus, #245c35); outline-offset: 4px; }@media (hover: hover) { .ds-primary:hover { background: var(--green-hover); } } @media (prefers-reduced-motion: reduce) { .ds-primary { transition: none; } }
